#!/usr/bin/env python3
"""
Data loading module for supplementary datasets.

Loads GESP scores, synthetic lethality data, competition data,
and indication mappings.
"""

import json
import logging
import time
from pathlib import Path
from typing import Any, Dict, List, Optional, Set, Tuple

import requests
import yaml
import polars as pl


class SupplementaryDataLoader:
    """Loader for all supplementary datasets used in analysis."""

    def __init__(self, project_root: Path, logger: logging.Logger = None):
        """
        Initialize data loader.

        Args:
            project_root: Path to project root directory
            logger: Logger instance (creates new one if not provided)
        """
        self.project_root = project_root
        self.logger = logger or logging.getLogger(__name__)

        # Data storage
        self.gesp_data: Dict[str, Dict[str, float]] = {}
        self.synleth_pairs: Set[Tuple[str, str]] = set()
        self.synleth_scores: Dict[Tuple[str, str], Dict] = {}
        self.competitor_data: Dict[str, Dict] = {}
        self.indication_mapping: Dict[str, Dict] = {}
        self.indication_to_primary_site: Dict[str, list] = {}
        self.protein_copy_numbers: Dict[str, Dict[str, Optional[float]]] = {}
        self.internalization_data: Dict[str, Dict] = {}
        self.endocytic_motif_scores: Dict[str, float] = {}
        self.gene_list_memberships: Dict[str, List[str]] = {}

    def load_all(self) -> None:
        """Load all supplementary datasets."""
        self.load_gesp_scores()
        self.load_synthetic_lethality()
        self.load_competitor_data()
        self.load_indication_mapping()
        self.load_pan_cancer_proteomics()
        self.load_internalization_data()
        self.load_endocytic_motif_scores()
        self.load_gene_list_memberships()

    def load_gesp_scores(self) -> None:
        """Load GESP (Gene Expression Surfaceome Predictor) scores."""
        gesp_file = self.project_root / "data/Hu_et_al_2021_GESPs.csv"

        if not gesp_file.exists():
            self.logger.warning(f"GESP file not found: {gesp_file}")
            return

        try:
            # Use semicolon as separator
            gesp_df = pl.read_csv(gesp_file, separator=';')

            # Create dictionary with gene symbol as key
            for row in gesp_df.iter_rows(named=True):
                gene = row.get("HGNC Symbol", "").strip()
                if gene:
                    # Clean up scores (replace comma with dot for decimals)
                    core_score = str(row.get("Core GESP Score ", "0")).replace(",", ".")
                    final_score = str(row.get("Final GESP Score ", "0")).replace(",", ".")
                    try:
                        self.gesp_data[gene] = {
                            "core": float(core_score),
                            "final": float(final_score)
                        }
                    except ValueError:
                        pass

            self.logger.info(f"Loaded GESP scores for {len(self.gesp_data)} genes")

        except Exception as e:
            self.logger.warning(f"Failed to load GESP data: {e}")

    def load_synthetic_lethality(self) -> None:
        """Load synthetic lethality data from DepMap and SynLethDB."""
        # Load DepMap synthetic lethality
        depmap_file = self.project_root / "data/depmap/synthetic_lethality_pairs.csv"
        if depmap_file.exists():
            try:
                depmap_df = pl.read_csv(depmap_file)
                for row in depmap_df.iter_rows(named=True):
                    gene1 = row["gene1"]
                    gene2 = row["gene2"]
                    pair_key = tuple(sorted([gene1, gene2]))
                    self.synleth_pairs.add(pair_key)

                    # Store score and metadata
                    if pair_key not in self.synleth_scores:
                        self.synleth_scores[pair_key] = {
                            "depmap_score": row.get("synthetic_lethality_score", 0),
                            "depmap_cell_lines": row.get("n_cell_lines", 0),
                            "sources": ["DepMap"]
                        }

                self.logger.info(f"Loaded {len(self.synleth_pairs)} DepMap synthetic lethal pairs")

            except Exception as e:
                self.logger.warning(f"Failed to load DepMap synthetic lethality: {e}")

        # Load SynLethDB
        synlethdb_file = self.project_root / "data/synlethdb/synlethdb_human_pairs.csv"
        if synlethdb_file.exists():
            try:
                synlethdb_df = pl.read_csv(synlethdb_file)
                for row in synlethdb_df.iter_rows(named=True):
                    gene1 = row["gene1"]
                    gene2 = row["gene2"]
                    pair_key = tuple(sorted([gene1, gene2]))
                    self.synleth_pairs.add(pair_key)

                    # Update or add score
                    if pair_key in self.synleth_scores:
                        self.synleth_scores[pair_key]["synlethdb_score"] = row.get("score", 0)
                        self.synleth_scores[pair_key]["synlethdb_evidence"] = row.get("evidence_count", 1)
                        self.synleth_scores[pair_key]["sources"].append("SynLethDB")
                    else:
                        self.synleth_scores[pair_key] = {
                            "synlethdb_score": row.get("score", 0),
                            "synlethdb_evidence": row.get("evidence_count", 1),
                            "sources": ["SynLethDB"]
                        }

                self.logger.info(f"Loaded SynLethDB pairs (total unique: {len(self.synleth_pairs)})")

            except Exception as e:
                self.logger.warning(f"Failed to load SynLethDB: {e}")

    def load_competitor_data(self) -> None:
        """Load ADC competitor landscape data.

        Gene names from competition.csv are normalized to HGNC symbols using
        batch_validate_genes() so that lookups match the HGNC-normalized gene
        names used throughout the pipeline (e.g. CD317 -> BST2).
        """
        competition_file = self.project_root / "data/competition.csv"

        if not competition_file.exists():
            self.logger.warning(f"Competition file not found: {competition_file}")
            return

        try:
            comp_df = pl.read_csv(competition_file)

            # First pass: collect all unique raw target names for batch normalization
            raw_targets = set()
            for row in comp_df.iter_rows(named=True):
                targets = row.get("targets_parsed", "")
                if targets:
                    for t in targets.replace(";", ",").split(","):
                        t = t.strip().upper()
                        if t:
                            raw_targets.add(t)

            # Normalize all target names to HGNC symbols in one batch
            from core import gene_validation
            hgnc_map = gene_validation.batch_validate_genes(list(raw_targets))
            n_mapped = sum(1 for v in hgnc_map.values() if v is not None)
            n_aliased = sum(1 for k, v in hgnc_map.items() if v is not None and v != k)
            self.logger.info(
                f"HGNC normalization: {len(raw_targets)} unique targets, "
                f"{n_aliased} alias(es) resolved (e.g. CD317->BST2)"
            )

            # Second pass: build competitor dictionary with normalized names
            for row in comp_df.iter_rows(named=True):
                targets = row.get("targets_parsed", "")
                if not targets:
                    continue

                # Parse and normalize targets
                raw_list = [t.strip().upper() for t in targets.replace(";", ",").split(",") if t.strip()]
                target_list = [hgnc_map.get(t, t) or t for t in raw_list]

                # Store data for each target
                for target in target_list:
                    if target not in self.competitor_data:
                        self.competitor_data[target] = {
                            "adcs": [],
                            "highest_stage": 0,
                            "bispecific_count": 0
                        }

                    # Add ADC info
                    adc_info = {
                        "name": row.get("drug_name", "Unknown"),
                        "company": row.get("company", "Unknown"),
                        "stage": row.get("stage", "Unknown"),
                        "stage_numeric": row.get("stage_numeric", 0),
                        "target_type": row.get("target_type", "monospecific"),
                        "all_targets": target_list
                    }

                    self.competitor_data[target]["adcs"].append(adc_info)

                    # Update highest stage
                    stage_num = row.get("stage_numeric", 0)
                    if stage_num > self.competitor_data[target]["highest_stage"]:
                        self.competitor_data[target]["highest_stage"] = stage_num

                    # Count bispecifics
                    if row.get("target_type", "").lower() == "bispecific":
                        self.competitor_data[target]["bispecific_count"] += 1

            self.logger.info(f"Loaded competitor data for {len(self.competitor_data)} targets")

        except Exception as e:
            self.logger.warning(f"Failed to load competitor data: {e}")

    def load_indication_mapping(self) -> None:
        """Load indication focus to TCGA/TARGET mapping."""
        mapping_file = self.project_root / "priority_indications" / "indication_to_tcga_mapping.csv"

        if not mapping_file.exists():
            self.logger.warning(f"Indication mapping file not found: {mapping_file}")
            return

        try:
            mapping_df = pl.read_csv(mapping_file)

            # Create mapping from tcga_disease (disease-specific) to indication metadata
            # This allows disease subtypes to inherit indication priority (e.g., all Kidney subtypes → Priority 2)
            for row in mapping_df.iter_rows(named=True):
                tcga_disease = row.get("tcga_disease")
                primary_site = row.get("tcga_primary_site")

                if tcga_disease and tcga_disease != "":
                    # Store indication metadata for this specific disease
                    self.indication_mapping[tcga_disease] = {
                        "indication_name": row.get("indication_name", ""),
                        "select": row.get("select", "No"),
                        "priority": row.get("priority"),  # Can be 1.0, 2.0, or NaN
                        "note": row.get("note", ""),
                        "tcga_disease": tcga_disease,
                        "tcga_primary_site": primary_site,
                        "mapping_confidence": row.get("mapping_confidence", "")
                    }

                    # Build reverse mapping (indication_name -> list of diseases)
                    indication_name = row.get("indication_name", "")
                    if indication_name:
                        if indication_name not in self.indication_to_primary_site:
                            self.indication_to_primary_site[indication_name] = []
                        if tcga_disease not in self.indication_to_primary_site[indication_name]:
                            self.indication_to_primary_site[indication_name].append(tcga_disease)

            self.logger.info(f"Loaded indication mapping for {len(self.indication_mapping)} cancer types")

            # Count priority indications
            priority1_count = len([k for k, v in self.indication_mapping.items()
                                  if v.get("select") == "Yes" and v.get("priority") == 1.0])
            priority2_count = len([k for k, v in self.indication_mapping.items()
                                  if v.get("select") == "Yes" and v.get("priority") == 2.0])
            self.logger.info(f"  Priority 1: {priority1_count} cancer types, Priority 2: {priority2_count} cancer types")

        except Exception as e:
            self.logger.warning(f"Failed to load indication mapping: {e}")

    def load_pan_cancer_proteomics(self) -> None:
        """Load Pan-Cancer Proteome Atlas data and compute per-gene summary statistics.

        Reads absolute protein copy numbers per cell from the surfaceome
        parquet file, filters for tumor samples (Primary cancer + Metastasis),
        and computes median copies/cell and detection rate for each gene.
        """
        surfaceome_file = self.project_root / "data/proteomics/pan_cancer_proteomics_surfaceome.parquet"
        metadata_file = self.project_root / "data/proteomics/pan_cancer_sample_metadata.parquet"

        if not surfaceome_file.exists() or not metadata_file.exists():
            self.logger.warning("Pan-cancer proteomics files not found, skipping")
            return

        try:
            metadata = pl.read_parquet(metadata_file)
            surfaceome = pl.read_parquet(surfaceome_file)

            # Get tumor sample IDs (Primary cancer + Metastasis)
            tumor_samples = (
                metadata
                .filter(pl.col("sample_type").is_in(["Primary cancer", "Metastasis"]))
                ["sample_id"]
                .to_list()
            )

            # Only keep sample columns that actually exist in the surfaceome data
            tumor_sample_cols = [s for s in tumor_samples if s in surfaceome.columns]
            total_tumor_samples = len(tumor_sample_cols)

            if total_tumor_samples == 0:
                self.logger.warning("No tumor samples found in proteomics data")
                return

            # Keep only unique-peptide rows per gene (gene_name == gene_symbol).
            # Shared-peptide rows (e.g. "PLXNB2;PLXNC1;PLXND1") inflate counts
            # when grouped by gene_symbol, leading to detection rates > 100%.
            if "gene_name" in surfaceome.columns:
                unique_peptide = surfaceome.filter(
                    pl.col("gene_name") == pl.col("gene_symbol")
                )
                # Fall back to first row per gene if no unique-peptide row exists
                unique_gene_set = unique_peptide["gene_symbol"].unique()
                remaining_genes = (
                    surfaceome
                    .filter(~pl.col("gene_symbol").is_in(unique_gene_set))
                    .group_by("gene_symbol")
                    .first()
                )
                surfaceome = pl.concat([unique_peptide, remaining_genes])

            # Vectorized computation via melt + group_by
            melted = (
                surfaceome
                .select(["gene_symbol"] + tumor_sample_cols)
                .melt(
                    id_vars="gene_symbol",
                    value_vars=tumor_sample_cols,
                    variable_name="sample_id",
                    value_name="copies",
                )
            )

            stats = (
                melted
                .group_by("gene_symbol")
                .agg([
                    pl.col("copies").filter(
                        pl.col("copies").is_not_null() & (pl.col("copies") > 0)
                    ).median().alias("median_copies"),
                    (pl.col("copies").is_not_null() & (pl.col("copies") > 0))
                    .sum().alias("n_detected"),
                ])
                .with_columns(
                    (pl.col("n_detected") / total_tumor_samples).alias("detection_rate")
                )
            )

            for row in stats.iter_rows(named=True):
                gene = row["gene_symbol"]
                if gene:
                    self.protein_copy_numbers[gene] = {
                        "median_copies": row["median_copies"],
                        "detection_rate": row["detection_rate"],
                    }

            self.logger.info(f"Loaded protein copy numbers for {len(self.protein_copy_numbers)} genes")

        except Exception as e:
            self.logger.warning(f"Failed to load pan-cancer proteomics: {e}")

    def get_protein_copy_numbers(self, gene: str) -> Dict[str, float]:
        """Get pan-cancer protein copy number statistics for a gene."""
        return self.protein_copy_numbers.get(gene, {"median_copies": 0.0, "detection_rate": 0.0})

    def get_gesp_scores(self, gene: str) -> Dict[str, float]:
        """Get GESP scores for a gene."""
        return self.gesp_data.get(gene, {"core": 0.0, "final": 0.0})

    def is_synthetic_lethal(self, gene1: str, gene2: str) -> bool:
        """Check if gene pair is synthetic lethal."""
        pair_key = tuple(sorted([gene1, gene2]))
        return pair_key in self.synleth_pairs

    def get_synthetic_lethality_info(self, gene1: str, gene2: str) -> Dict:
        """Get synthetic lethality information for gene pair."""
        pair_key = tuple(sorted([gene1, gene2]))
        return self.synleth_scores.get(pair_key, {})

    def get_competitor_info(self, gene: str) -> Dict:
        """Get competitor ADC information for a gene."""
        gene_upper = gene.upper()
        return self.competitor_data.get(gene_upper, {
            "adcs": [],
            "highest_stage": 0,
            "bispecific_count": 0
        })

    def load_internalization_data(self) -> None:
        """Load curated internalization data from CSV.

        Reuses the same curated CSV as helpers/internalization_helper.py but
        without Streamlit dependencies. Only loads the curated (ADC-validated)
        data -- GO API calls are not suitable for batch processing.
        """
        curated_file = self.project_root / "data/internalization_curated.csv"

        if not curated_file.exists():
            self.logger.warning(f"Internalization data not found: {curated_file}")
            return

        try:
            df = pl.read_csv(curated_file)
            for row in df.iter_rows(named=True):
                gene = row.get("gene_symbol", "").strip()
                if gene:
                    self.internalization_data[gene] = {
                        "internalization_speed": row.get("internalization_speed"),
                        "endocytic_pathway": row.get("endocytic_pathway"),
                        "intracellular_fate": row.get("intracellular_fate"),
                        "constitutive": row.get("constitutive"),
                    }
            self.logger.info(f"Loaded internalization data for {len(self.internalization_data)} genes")
        except Exception as e:
            self.logger.warning(f"Failed to load internalization data: {e}")

    def get_internalization(self, gene: str) -> Dict:
        """Get internalization data for a gene."""
        return self.internalization_data.get(gene, {
            "internalization_speed": "",
            "endocytic_pathway": "",
            "intracellular_fate": "",
            "constitutive": "",
        })

    def _fetch_uniprot_topology(self, gene_symbol: str) -> Optional[Dict[str, Any]]:
        """Fetch sequence + topology features from UniProt for a single gene.

        Returns dict with 'sequence' and 'topology' keys, or None on failure.
        """
        try:
            url = (
                f"https://rest.uniprot.org/uniprotkb/search"
                f"?query=gene_exact:{gene_symbol}+AND+organism_id:9606+AND+reviewed:true"
                f"&format=json&size=1"
            )
            resp = requests.get(url, timeout=5)
            if resp.status_code != 200:
                return None

            results = resp.json().get("results", [])
            if not results:
                return None

            entry = results[0]
            sequence = entry.get("sequence", {}).get("value", "")
            topology = []
            for feat in entry.get("features", []):
                if feat.get("type") in ("Transmembrane", "Topological domain"):
                    topology.append({
                        "type": feat["type"],
                        "description": feat.get("description", ""),
                        "start": feat.get("location", {}).get("start", {}).get("value", 0),
                        "end": feat.get("location", {}).get("end", {}).get("value", 0),
                    })

            return {"sequence": sequence, "topology": topology}
        except Exception:
            return None

    def load_endocytic_motif_scores(self) -> None:
        """Compute Endocytic Motif Scores for all known genes.

        Uses a disk cache (data/cache/uniprot_topology.json) to avoid
        repeated API calls across runs. Only genes not yet in the cache
        are fetched from UniProt.
        """
        from helpers.internalization_helper import compute_endocytic_motif_score

        cache_dir = self.project_root / "data" / "cache"
        cache_dir.mkdir(parents=True, exist_ok=True)
        cache_file = cache_dir / "uniprot_topology.json"

        # Load existing cache
        cache: Dict[str, Any] = {}
        if cache_file.exists():
            try:
                with open(cache_file, "r") as f:
                    cache = json.load(f)
                self.logger.info(f"Loaded UniProt topology cache: {len(cache)} genes")
            except Exception as e:
                self.logger.warning(f"Failed to load topology cache: {e}")

        # Collect all genes we know about
        all_genes: Set[str] = set()
        all_genes.update(self.gesp_data.keys())
        all_genes.update(self.competitor_data.keys())
        all_genes.update(self.internalization_data.keys())

        # Fetch missing genes
        missing = [g for g in all_genes if g not in cache]
        if missing:
            self.logger.info(
                f"UniProt topology: {len(cache)} cached, {len(missing)} to fetch"
            )
            fetched = 0
            failed = 0
            failed_genes: list[str] = []
            start_time = time.time()

            for i, gene in enumerate(missing, 1):
                result = self._fetch_uniprot_topology(gene)
                if result is not None:
                    cache[gene] = result
                    fetched += 1
                else:
                    cache[gene] = {"sequence": "", "topology": []}
                    failed += 1
                    if len(failed_genes) < 20:
                        failed_genes.append(gene)

                if i % 100 == 0 or i == len(missing):
                    elapsed = time.time() - start_time
                    rate = i / elapsed if elapsed > 0 else 0
                    eta = (len(missing) - i) / rate if rate > 0 else 0
                    self.logger.info(
                        f"  UniProt fetch: {i}/{len(missing)} "
                        f"({fetched} OK, {failed} failed) "
                        f"[{elapsed:.0f}s elapsed, ~{eta:.0f}s remaining]"
                    )

            if failed_genes:
                self.logger.warning(
                    f"UniProt fetch failed for {failed} genes: "
                    f"{', '.join(failed_genes[:10])}"
                    f"{'...' if len(failed_genes) > 10 else ''}"
                )

            # Save updated cache
            try:
                with open(cache_file, "w") as f:
                    json.dump(cache, f)
            except Exception as e:
                self.logger.warning(f"Failed to save topology cache: {e}")

        # Compute EMS for all cached genes
        scored = 0
        for gene in all_genes:
            entry = cache.get(gene, {})
            seq = entry.get("sequence", "")
            topo = entry.get("topology", [])
            if seq and topo:
                score = compute_endocytic_motif_score(seq, topo)
                if score > 0:
                    self.endocytic_motif_scores[gene] = score
                    scored += 1

        self.logger.info(
            f"Computed endocytic motif scores: {scored} genes with score > 0 "
            f"(of {len(all_genes)} total)"
        )

    def load_gene_list_memberships(self) -> None:
        """Load gene list memberships by scanning YAML configs and competition data.

        Builds a mapping of gene_symbol -> list of list names (e.g. ["pioneer_novel", "competitor_target"]).
        """
        configs_dir = self.project_root / "automated_analysis" / "configs"

        # Scan YAML configs for gene lists
        if configs_dir.exists():
            for yaml_file in configs_dir.glob("*.yaml"):
                try:
                    with open(yaml_file, 'r') as f:
                        config = yaml.safe_load(f)

                    analysis_name = config.get("analysis_name", yaml_file.stem)

                    # Skip universal_pool config (it's this analysis, not a curated list)
                    if analysis_name == "universal_pool":
                        continue

                    input_config = config.get("input", {})
                    file_path = input_config.get("file_path")
                    if not file_path:
                        continue

                    gene_list_path = self.project_root / file_path
                    if not gene_list_path.exists():
                        self.logger.warning(f"Gene list not found for {analysis_name}: {gene_list_path}")
                        continue

                    # Read the gene list
                    if gene_list_path.suffix == '.csv':
                        gene_df = pl.read_csv(gene_list_path)
                        # Try common column names
                        for col in ["gene", "Gene", "gene_symbol", "Gene1"]:
                            if col in gene_df.columns:
                                genes = gene_df[col].to_list()
                                break
                        else:
                            genes = gene_df[gene_df.columns[0]].to_list()
                    else:
                        with open(gene_list_path, 'r') as f:
                            content = f.read().strip()
                        genes = [g.strip() for g in content.replace(',', '\n').split('\n') if g.strip()]

                    for gene in genes:
                        gene = str(gene).strip()
                        if gene:
                            if gene not in self.gene_list_memberships:
                                self.gene_list_memberships[gene] = []
                            if analysis_name not in self.gene_list_memberships[gene]:
                                self.gene_list_memberships[gene].append(analysis_name)

                    self.logger.info(f"Loaded {len(genes)} genes from {analysis_name}")

                except Exception as e:
                    self.logger.warning(f"Failed to parse config {yaml_file.name}: {e}")

        # Tag competitor targets
        for gene in self.competitor_data:
            if gene not in self.gene_list_memberships:
                self.gene_list_memberships[gene] = []
            if "competitor_target" not in self.gene_list_memberships[gene]:
                self.gene_list_memberships[gene].append("competitor_target")

        self.logger.info(f"Loaded gene list memberships for {len(self.gene_list_memberships)} genes")

    def get_gene_lists(self, gene: str) -> str:
        """Get comma-separated list of gene list memberships for a gene."""
        lists = self.gene_list_memberships.get(gene, [])
        return ", ".join(lists) if lists else ""

    def get_indication_metadata(self, cancer_type: str) -> Dict:
        """Get indication metadata for a cancer type."""
        return self.indication_mapping.get(cancer_type, {})

    def to_shared_dict(self) -> Dict[str, Any]:
        """Export all data as a flat dict for the standalone process_pair() function.

        Returns a canonical dict whose keys are read by process_pair() in
        pair_analyzer.py.  Adding a new data source here automatically
        makes it available to both sequential and parallel execution.
        """
        return {
            'gesp_scores': self.gesp_data,
            'competition': self.competitor_data,
            'indication_map': self.indication_mapping,
            'synleth_pairs': self.synleth_pairs,
            'synleth_scores': self.synleth_scores,
            'protein_copy_numbers': self.protein_copy_numbers,
            'internalization': self.internalization_data,
            'endocytic_motif_scores': self.endocytic_motif_scores,
            'gene_list_memberships': self.gene_list_memberships,
        }

