def run(self):
    """Execute analysis workflow, dispatching to the appropriate mode.

    Single-sweep execution: one run analyzes every gene pair at every
    available transcript combination. Canonical transcripts are annotated
    on `transcript_metadata.is_canonical` so the UI can filter at query
    time without gating the pipeline. Interrupt-safe: re-running the same
    config resumes from the same run_id.
    """
    try:
        if self.config.update_mode:
            return self._run_partial_update()
        elif self.config.incremental:
            return self._run_incremental()
        else:
            return self._run_full()

    except KeyboardInterrupt:
        self.logger.info("\n\nAnalysis interrupted by user")
        self.logger.info(
            "Progress saved to DuckDB. Re-run the same command to resume."
            if self.db_writer is not None
            else "Analysis stopped."
        )
        return 130
    except Exception as e:
        self.logger.error(f"\nAnalysis failed: {e}", exc_info=True)
        return 1
    finally:
        if self.db_writer is not None:
            self.db_writer.close()

def _compute_run_id(self) -> str:
    """Derive a deterministic run_id from config parameters.

    Re-running the same config resumes the same run; changing any
    parameter that affects results produces a new run automatically.
    """
    parts = [
        self.config.analysis_name or "unnamed",
        f"or{self.config.or_percentile}",
        f"and{self.config.and_percentile}",
        f"tier-{self.config.tissue_tier}",
        f"tpm{self.config.min_tpm_threshold}",
        f"gesp{self.config.gesp_threshold}",
        f"src-{self.config.input_source}",
    ]
    digest = hashlib.sha1("|".join(str(p) for p in parts).encode()).hexdigest()[:8]
    return f"{self.config.analysis_name or 'unnamed'}__{digest}"

def _annotate_canonical_transcripts(
    self, all_gene_transcripts: list
) -> dict:
    """Resolve canonical transcript per gene for metadata annotation.

    Returns a dict mapping transcript_id -> canonical_source for every
    canonical transcript. Non-canonical transcripts are not in the dict.
    """
    gene_groups: dict = {}
    for g in all_gene_transcripts:
        gene_groups.setdefault(g["gene_name"], []).append(g)

    resolver = self.gene_manager.canonical_resolver
    canonical_map: dict = {}
    for gene_symbol, transcripts in gene_groups.items():
        resolved = resolver.resolve(gene_symbol, transcripts)
        if resolved:
            canonical_map[resolved["transcript_id"]] = "canonical_resolver"
    return canonical_map

