def _annotate_canonical_transcripts(
    self, all_gene_transcripts: list
) -> dict:
    """Resolve canonical transcript per gene for metadata annotation.

    Returns a dict mapping transcript_id -> canonical_source for every
    canonical transcript. Non-canonical transcripts are not in the dict.
    """
    gene_groups: dict = {}
    for g in all_gene_transcripts:
        gene_groups.setdefault(g["gene_name"], []).append(g)

    resolver = self.gene_manager.canonical_resolver
    canonical_map: dict = {}
    for gene_symbol, transcripts in gene_groups.items():
        resolved = resolver.resolve(gene_symbol, transcripts)
        if resolved:
            canonical_map[resolved["transcript_id"]] = "canonical_resolver"
    return canonical_map

