def load_gene_list_memberships(self) -> None:
    """Load gene list memberships by scanning YAML configs and competition data.

    Builds a mapping of gene_symbol -> list of list names (e.g. ["pioneer_novel", "competitor_target"]).
    """
    configs_dir = self.project_root / "automated_analysis" / "configs"

    # Scan YAML configs for gene lists
    if configs_dir.exists():
        for yaml_file in configs_dir.glob("*.yaml"):
            try:
                with open(yaml_file, 'r') as f:
                    config = yaml.safe_load(f)

                analysis_name = config.get("analysis_name", yaml_file.stem)

                # Skip universal_pool config (it's this analysis, not a curated list)
                if analysis_name == "universal_pool":
                    continue

                input_config = config.get("input", {})
                file_path = input_config.get("file_path")
                if not file_path:
                    continue

                gene_list_path = self.project_root / file_path
                if not gene_list_path.exists():
                    self.logger.warning(f"Gene list not found for {analysis_name}: {gene_list_path}")
                    continue

                # Read the gene list
                if gene_list_path.suffix == '.csv':
                    gene_df = pl.read_csv(gene_list_path)
                    # Try common column names
                    for col in ["gene", "Gene", "gene_symbol", "Gene1"]:
                        if col in gene_df.columns:
                            genes = gene_df[col].to_list()
                            break
                    else:
                        genes = gene_df[gene_df.columns[0]].to_list()
                else:
                    with open(gene_list_path, 'r') as f:
                        content = f.read().strip()
                    genes = [g.strip() for g in content.replace(',', '\n').split('\n') if g.strip()]

                for gene in genes:
                    gene = str(gene).strip()
                    if gene:
                        if gene not in self.gene_list_memberships:
                            self.gene_list_memberships[gene] = []
                        if analysis_name not in self.gene_list_memberships[gene]:
                            self.gene_list_memberships[gene].append(analysis_name)

                self.logger.info(f"Loaded {len(genes)} genes from {analysis_name}")

            except Exception as e:
                self.logger.warning(f"Failed to parse config {yaml_file.name}: {e}")

    # Tag competitor targets
    for gene in self.competitor_data:
        if gene not in self.gene_list_memberships:
            self.gene_list_memberships[gene] = []
        if "competitor_target" not in self.gene_list_memberships[gene]:
            self.gene_list_memberships[gene].append("competitor_target")

    self.logger.info(f"Loaded gene list memberships for {len(self.gene_list_memberships)} genes")

