@st.cache_data(ttl=3600)
def load_indication_mapping():
    """Load priority indication to TCGA disease mapping."""
    mapping_df = pd.read_csv("priority_indications/indication_to_tcga_mapping.csv")
    # Filter for selected indications with valid TCGA diseases
    selected = mapping_df[
        (mapping_df["select"] == "Yes") & mapping_df["tcga_disease"].notna()
    ]
    p1 = set(selected.loc[selected["priority"] == 1.0, "tcga_disease"].unique())
    p2 = set(selected.loc[selected["priority"] == 2.0, "tcga_disease"].unique())
    return {"priority_1": p1, "priority_2": p2, "all_priority": p1 | p2}

