@classmethod
def from_dict(cls, data: dict) -> 'TargetAssessment':
    """Create from dictionary."""
    valid_fields = {k: v for k, v in data.items() if k in cls.__dataclass_fields__}
    return cls(**valid_fields)

@classmethod
def from_blacklist_entry(
    cls,
    gene: str,
    category: str,
    reason: str,
    source: str = ""
) -> 'TargetAssessment':
    """Create Excluded assessment from legacy blacklist entry."""
    return cls(
        gene_symbol=gene.upper(),
        verdict="Excluded",
        include_in_analysis=False,
        exclusion_category=category,
        safety_notes=reason,
        key_concerns=reason,
        recommendation=f"Excluded: {category}",
        monospecific_feasible="No",
        last_updated=datetime.now().isoformat(),
        updated_by=f"Migrated from blacklist ({source})" if source else "Migrated from blacklist",
    )

